package inventory

import "sort"

// ReorderAt 是补货阈值：数量低于它的条目需要补货。
const ReorderAt = 5

// Item 是库存里的一条记录。
type Item struct {
	SKU string
	Qty int
}

// Stock ...
func Stock(...)

// Reorder 返回数量低于 ReorderAt 的条目，按数量升序、数量相同按 SKU 升序排列。
func Reorder(items []Item) []Item {
	low := make([]Item, 0, len(items))
	for _, it := range items {
		if it.Qty < ReorderAt {
			low = append(low, it)
		}
	}
	sort.SliceStable(low, func(i, j int) bool {
		if low[i].Qty != low[j].Qty {
			return low[i].Qty < low[j].Qty
		}
		return low[i].SKU < low[j].SKU
	})
	return low
}
```

