func TestReorderFiltersAndSorts(t *testing.T) {
	items := []Item{
		{SKU: "b", Qty: 3},
		{SKU: "a", Qty: 3},
		{SKU: "z", Qty: 9},
		{SKU: "a", Qty: 1},
		{SKU: "d", Qty: 0},
		{SKU: "e", Qty: ReorderAt},
	}
	got := Reorder(items)
	want := []Item{
		{SKU: "d", Qty: 0},
		{SKU: "a", Qty: 1},
		{SKU: "a", Qty: 3},
		{SKU: "b", Qty: 3},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder() = %#v，想要 %#v", got, want)
	}
}

func TestReorderEmpty(t *testing.T) {
	if got := Reorder(nil); len(got) != 0 {
		t.Fatalf("Reorder(nil) = %#v，想要空", got)
	}
	items := []Item{{SKU: "a", Qty: ReorderAt}, {SKU: "b", Qty: 10}}
	if got := Reorder(items); len(got) != 0 {
		t.Fatalf("Reorder(全部达标) = %#v，想要空", got)
	}
}

func TestReorderDoesNotMutateInput(t *testing.T) {
	items := []Item{{SKU: "b", Qty: 3}, {SKU: "a", Qty: 1}}
	before := append([]Item(nil), items...)
	Reorder(items)
	if !reflect.DeepEqual(items, before) {
		t.Fatalf("Reorder 修改了入参：%#v，原本 %#v", items, before)
	}
}
